<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $layout = sd_homepage_get( 'sd_home_hero_layout' ); $primary_url = sd_homepage_destination( sd_homepage_get( 'sd_home_hero_primary_url' ), sd_homepage_join_url() ); $secondary_url = sd_homepage_destination( sd_homepage_get( 'sd_home_hero_secondary_url' ), sd_homepage_explore_url() ); $image_id = absint( sd_homepage_get( 'sd_home_hero_image' ) ); ?><section class="sd-home-hero sd-home-hero-<?php echo esc_attr( $layout ); ?> sd-home-align-<?php echo esc_attr( sd_homepage_get( 'sd_home_hero_alignment' ) ); ?>" style="--sd-hero-background:<?php echo esc_attr( sd_homepage_get( 'sd_home_hero_background' ) ); ?>;--sd-hero-overlay-opacity:<?php echo esc_attr( absint( sd_homepage_get( 'sd_home_hero_overlay_opacity' ) ) / 100 ); ?>"><div class="sd-container sd-home-hero-inner"><div class="sd-home-hero-copy"><span class="sd-eyebrow"><?php echo esc_html( sd_homepage_get( 'sd_home_hero_eyebrow' ) ); ?></span><h1><?php echo esc_html( sd_homepage_get( 'sd_home_hero_heading' ) ); ?></h1><p><?php echo esc_html( sd_homepage_get( 'sd_home_hero_description' ) ); ?></p><div class="sd-hero-actions"><a class="sd-button sd-button-primary" href="<?php echo esc_url( $primary_url ); ?>"><?php echo esc_html( sd_homepage_get( 'sd_home_hero_primary_text' ) ); ?></a><a class="sd-button sd-button-outline" href="<?php echo esc_url( $secondary_url ); ?>"><?php echo esc_html( sd_homepage_get( 'sd_home_hero_secondary_text' ) ); ?></a></div></div><?php if ( $image_id ) : ?><div class="sd-home-hero-media"><?php echo wp_get_attachment_image( $image_id, 'sd-home-hero', false, array( 'loading' => 'eager', 'class' => 'sd-home-hero-image' ) ); ?></div><?php else : ?><div class="sd-home-hero-art" aria-hidden="true"><span></span><span></span><span></span></div><?php endif; ?></div></section>
